MERGE INTO employees e USING (SELECT 'alice.johnson@example.com' email FROM dual) s ON (e.email=s.email) WHEN NOT MATCHED THEN INSERT (first_name,last_name,email,phone_number,department,designation,joining_date,employment_status) VALUES ('Alice','Johnson',s.email,'+1 555 0101','Engineering','Software Engineer',DATE '2023-01-15','ACTIVE');
