MERGE INTO app_users u USING (SELECT 'admin@example.com' email FROM dual) s ON (u.email=s.email) WHEN NOT MATCHED THEN INSERT (name,email,password) VALUES ('Admin',s.email,'$2a$10$N9qo8uLOickgx2ZMRZoMyeIjZAgcfl7p92ldGxad68LJZdL17lhWy');
