MERGE INTO attendance_records a USING (SELECT id employee_id FROM employees WHERE email='alice.johnson@example.com') s ON (a.employee_id=s.employee_id AND a.attendance_date=DATE '2025-01-06') WHEN NOT MATCHED THEN INSERT (employee_id,attendance_date,attendance_status,check_in_time,check_out_time,total_working_hours,remarks) VALUES (s.employee_id,DATE '2025-01-06','PRESENT',TIMESTAMP '1970-01-01 09:00:00',TIMESTAMP '1970-01-01 17:30:00',8.50,'Regular day');
MERGE INTO attendance_records a USING (SELECT id employee_id FROM employees WHERE email='bob.smith@example.com') s ON (a.employee_id=s.employee_id AND a.attendance_date=DATE '2025-01-06') WHEN NOT MATCHED THEN INSERT (employee_id,attendance_date,attendance_status,check_in_time,check_out_time,total_working_hours,remarks) VALUES (s.employee_id,DATE '2025-01-06','HALF_DAY',TIMESTAMP '1970-01-01 09:15:00',TIMESTAMP '1970-01-01 13:15:00',4.00,'Medical appointment');
MERGE INTO attendance_records a USING (SELECT id employee_id FROM employees WHERE email='carol.davis@example.com') s ON (a.employee_id=s.employee_id AND a.attendance_date=DATE '2025-01-06') WHEN NOT MATCHED THEN INSERT (employee_id,attendance_date,attendance_status,check_in_time,check_out_time,total_working_hours,remarks) VALUES (s.employee_id,DATE '2025-01-06','ABSENT',NULL,NULL,0.00,'Approved leave');
